#include <iostream>
using namespace std;

bool isPrime[1005];

int main() {
    int n;
    cin >> n;
    for (int i = 2; i <= n; i++) isPrime[i] = true;
    for (int i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) isPrime[j] = false;
        }
    }
    return 0;
}
